) INSERT INTO releases (listing_key, release_id, artist, title, label_name, format, release_year, media_condition, sleeve_condition, notes, price_cad, quantity, status, category, discogs_image_url, custom_image_url, popularity_score, is_hidden) SELECT incoming.listing_key, incoming.release_id, incoming.artist, incoming.title, incoming.label_name, incoming.format, incoming.release_year, incoming.media_condition, incoming.sleeve_condition, incoming.notes, incoming.price_cad, incoming.quantity, incoming.status, incoming.category, incoming.discogs_image_url, incoming.custom_image_url, incoming.popularity_score, incoming.is_hidden FROM incoming WHERE NOT EXISTS (SELECT 1 FROM releases existing WHERE existing.listing_key = incoming.listing_key);
